window.POETRY_REGISTER("v5-extra-13-13-0-6b72966d3a20.js",{"poems":[[109554,7],[143405,7],[270369,7],[288132,7],[288143,7],[365412,9],[488527,8],[516668,8],[589734,8],[593805,8],[650074,5],[653286,5],[703603,5],[744367,21]],"pairs":[["并禹稷之圣贤兮实惟桓拨之王","历妫姒之世数兮道日跻于武汤",0],["始伐罪于仇饷兮人怨咨而徯来","顾寛仁之宜民兮天俾式于九围",0],["谅除残而代虐兮犹云德之有惭","赖燕翼于孙谋兮治克举于三宗",0],["寔遭家之不嗣兮顾丽色之惟微","念社稷之颠倾兮七庙无所凭依",0],["帝眷在于有周兮抱祭器而焉归","虽白马之见庙兮聊血食于商丘",0],["彼天地其孰始兮日与月其代除","四荒漫其何极兮人胡为而中居",1],["火何为而南宅兮水孰使其在北","安知东之主生兮西配刑而主杀",1],["爰升清而降浊兮水赴阴而火阳","东升气而敷生兮西或成而害戕",1],["苟待予而后造兮彼造予者复谁","姑置之而勿校兮任万物之自成",1],["乐吾心之洋洋兮舒五体之与与","降复还于我室兮聊弥日而一娱",1],["坚刚正独盘薄偃蹇受命不受封","无用之用不器之器振古成自晚",2],["不忮不求兮未尝偭绳墨而改错","视万马之奔逸兮歛组辔而独驻",3],["握异采之陆离兮蹇儃佪而逶迤","袭正轨之茂则兮耻践迹而循科",4],["神藐藐而上征兮诉纬繣于太和","忽修灵之聿皇兮任侏儒之傞傞",4],["穷千里以逞毒兮岂此土为匪民","岁丁未而孕孽兮俶九厄之遘凶",5],["仰九关而往愬兮予踆踆其屡止","曰无往而勿复兮其悔祸之汝俟",5],["曰无往而勿复兮其悔祸之汝俟","胡披猖而荐肆兮将穷菑乎今兹",5],["胡披猖而荐肆兮将穷菑乎今兹","扇虐燄于荧荧兮导伯强使先之",5],["扇虐燄于荧荧兮导伯强使先之","怒气㶿其如饙兮憯薄人之四肢",5],["夙矫翼以方翔兮溯芳风而委羽","川激湍以东注兮弗盈科而奄沮",6],["嗟状元及第气干青云身依日月","犹不忘随处体认天理六字微诀",7],["犹不忘随处体认天理六字微诀","大学格致诚正修齐治平一囊括",7],["大学格致诚正修齐治平一囊括","经筵进讲启心沃心可以从头说",7],["经筵进讲启心沃心可以从头说","嗟石鹿子为天下得人知人之哲",7],["嗟石鹿子为天下得人知人之哲","为邦家之光为斯文如笺之不绝",7],["彼器溢而𫗧覆兮乐曾不免乎忧","谋人国而不善兮宁颠蹶之愆尤",8],["听风泉之泠泠兮忘陋巷之为居","无毁誉之拂膺兮无简书之侮予",9],["到后来他的寡妇孤儿又被人欺","我想那老贼一生得意没弄好脸",10],["终日酩酊淋漓嬉笑怒骂聊快意","请与酒人构一凌云烁日之高堂",11],["物无心而成化兮觉天地之无私","纷欣欣而茂育兮身亦游于化机",12],["亭檐隅以逍遥兮盻太虚以仰观","望阊阖之昭晰兮丽紫微之晖焕",13]]});
